render_session_header(2, 'Create the Semantic View', '9:35 AM – 10:00 AM', '25 min', 'AIRLINE_OPS_SV semantic view with metrics for Cortex Analyst')

render_technologies_used([{'name': 'Semantic View', 'description': 'A first-class object describing tables, relationships, facts, dimensions and metrics in business terms.', 'icon': 'description'}, {'name': 'Cortex Analyst', 'description': 'Text-to-SQL that uses the semantic view to answer natural-language questions.', 'icon': 'chat'}, {'name': 'Verified Queries', 'description': 'Trusted question/SQL pairs that improve accuracy for common questions.', 'icon': 'verified'}])

render_prompt('Prompt 2.1', 'Generate the semantic view', "Create a semantic view called AIRLINE_OPS_SV in AIRLINE_OPS.OPS over FACT_BOOKING, DIM_FLIGHT, DIM_PASSENGER and DIM_AIRPORT.\n- Relationships: bookings -> flights (FLIGHT_ID), bookings -> passengers (PASSENGER_ID), flights -> origin airport and flights -> destination airport (DIM_AIRPORT used twice, aliased ORIGIN_AIRPORT and DESTINATION_AIRPORT)\n- Dimensions: flight date (with year, month, quarter), cabin class, booking channel, booking status, Aeroplan tier, aircraft type, flight status, route (origin-destination), airport city, country, region\n- Facts: fares, taxes, seats booked, seat capacity, distance, departure delay minutes, Aeroplan points\n- Metrics: total revenue (CAD), number of bookings, number of flights, number of passengers, average fare, on-time performance % (flights with delay <= 15 min / flown flights), cancellation rate, load factor (seats booked / seat capacity)\n- Synonyms (e.g. revenue = sales/ticket revenue, OTP = on-time performance, pax = passengers, YUL = Montreal)\n- Instruction: fiscal year = calendar year; 'this year' = 2026, 'last year' = 2025; winter = December to February (e.g. last winter = Dec 2025 to Feb 2026), summer = June to August; exclude CANCELLED and REFUNDED bookings from revenue\nExecute and confirm with DESCRIBE SEMANTIC VIEW.")

render_prompt('Prompt 2.2', 'Test with natural-language questions', 'Using Cortex Analyst on AIRLINE_OPS.OPS.AIRLINE_OPS_SV, answer and show SQL for:\n1. What was total revenue this year vs last year by month?\n2. Which 5 routes have the highest revenue in 2026?\n3. What is on-time performance by hub airport (YUL, YYZ, YVR, YYC) for last winter?\n4. What share of revenue comes from Business class by Aeroplan tier?')
render_explanation("What this prompt does", 'Check each SQL: is the revenue filter applied, is year-over-year correct, are the two airport roles (origin vs destination) handled? Anything wrong becomes a fix in Prompt 2.3.')

render_prompt('Prompt 2.3', 'Add verified queries', 'Add the correct questions/SQL from the previous test as verified queries in AIRLINE_OPS_SV, fix any metric or synonym that produced a wrong answer, and re-run question 3 to confirm.')

render_key_concepts([{'term': 'Facts vs metrics', 'definition': 'Facts are row-level numeric values; metrics are aggregations (SUM, AVG, ratios) defined once and reused.'}, {'term': 'Role-playing dimension', 'definition': 'One dimension table joined twice with different meanings, like origin and destination airport.'}])

render_what_you_built(['AIRLINE_OPS_SV semantic view', 'Validated YoY, route, OTP and cabin questions', 'Verified queries'])
